import itertools
from collections import deque

def generate_k14_edges():
    """Generate all edges of K_14"""
    edges = []
    for u in range(14):
        for v in range(u+1, 14):
            edges.append((u, v))
    return edges

def vertex_connectivity(n, edges):
    """Compute vertex connectivity by finding minimum vertex cut"""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check if graph is connected
    def is_connected(removed):
        # Find first non-removed vertex
        start = None
        for i in range(n):
            if i not in removed:
                start = i
                break
        if start is None:
            return True  # All vertices removed

        # BFS
        visited = set()
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in removed and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        # Check if all non-removed vertices are visited
        for i in range(n):
            if i not in removed and i not in visited:
                return False
        return True

    # Try removing k vertices for k = 1, 2, ...
    for k in range(1, n):
        for removed in itertools.combinations(range(n), k):
            removed_set = set(removed)
            if not is_connected(removed_set):
                return k
    return n - 1

# Generate K_14
