print(f"Number of edges in K_14: {len(edges)}")
conn = vertex_connectivity(14, edges)
print(f"Vertex connectivity of K_14: {conn}")

# Let's also try a sparser graph - circulant graph C_14(1,2,3)
def generate_circulant(n, jumps):
    edges = set()
    for i in range(n):
        for j in jumps:
            u = i
            v = (i + j) % n
            if u > v:
                u, v = v, u
            if u != v:
                edges.add((u, v))
    return list(edges)

